 'http://unlimited.c.h5.admin.web.v2.fangdichan.shiqu.suzhou.dev.zhi.com/version.json'
)
foreach($u in $cands){
 try{ $r=Invoke-WebRequest -Uri $u -TimeoutSec 10 -UseBasicParsing; Write-Host "OK $u => $($r.StatusCode) len=$($r.RawContentLength)"; if($u -like '*version.json'){ Write-Host $r.Content } elseif($r.Content -match '<title>(.*?)</title>'){ Write-Host "TITLE: $($matches[1])" } }
 catch{ Write-Host "FAIL $u => $($_.Exception.Message)" }
}

$ErrorActionPreference='Continue'
$base='http://192.168.1.199:8081/api/v3.0'
[Console]::OutputEncoding=[Text.Encoding]::UTF8
try{
 $login=Invoke-RestMethod -Uri "$base/portal/login/login" -Method Post -ContentType 'application/json; charset=utf-8' -Body ([Text.Encoding]::UTF8.GetBytes((@{userName='admin';password='Zs@2026Aa!'}|ConvertTo-Json))) -TimeoutSec 15
 Write-Host "LOGIN code=$($login.code) msg=$($login.msg)"
 $token=$login.data.token
 Write-Host "token len=$($token.Length)"
 $H=@{Authorization=$token}
 $d=Invoke-RestMethod -Uri "$base/portal/user/detail?userId=1" -Method Post -Headers $H -Body '{}' -TimeoutSec 15
 Write-Host "roleIds=$($d.data.roleIds -join ',') terminalType=$($d.data.terminalType) nick=$($d.data.nickName)"
 foreach($rid in $d.data.roleIds){
   $rr=Invoke-RestMethod -Uri "$base/portal/role/detail?roleId=$rid" -Method Post -Headers $H -Body '{}' -TimeoutSec 15
