 $p.data | Where-Object {$_ -like '*bizSection*' -or $_ -eq '*:*:*'} | ForEach-Object { Write-Host "  PERM: $_" }
}catch{
 Write-Host "ERR $($_.Exception.Message)"
 if($_.Exception.Response){ $rd=New-Object IO.StreamReader($_.Exception.Response.GetResponseStream()); [Console]::WriteLine($rd.ReadToEnd()) }
}

