import { chromium } from 'playwright'

const BASE = 'http://127.0.0.1:8092'
const user = process.env.D_USER || 'admin'
const pass = process.env.D_PASS || 'Zs@2026Aa!'

const browser = await chromium.launch({ headless: true })
const ctx = await browser.newContext({ viewport: { width: 1920, height: 953 } })
const page = await ctx.newPage()
const logs = []
page.on('console', m => logs.push(`[${m.type()}] ${m.text()}`))

async function dumpStore(tag) {
  const s = await page.evaluate(() => {
    const st = window.__store__ || (document.querySelector('#app')?.__vue__?.$store)
    const out = {}
    try {
      const u = st.state.user
      out.roles = u.roles
      out.permissions = (u.permissions || []).filter(p => p === '*:*:*' || p.includes('bizSection'))
      out.terminalType = u.terminalType
      out.isSuperAdmin = st.getters.isSuperAdmin
    } catch (e) { out.err = String(e) }
    return out
  }).catch(e => ({ evalErr: String(e) }))
  console.log(`STORE[${tag}]:`, JSON.stringify(s))
}

try {
  await page.goto(BASE + '/#/login', { waitUntil: 'networkidle', timeout: 30000 })
  await page.waitForTimeout(1500)
  // try locate inputs
  const inputs = page.locator('input')
  const n = await inputs.count()
  console.log('inputs count:', n, 'url:', page.url())
  // fill username/password by placeholder or type
  const uSel = page.locator('input').first()
  await uSel.fill(user).catch(()=>{})
  const pSel = page.locator('input[type=password]').first()
  await pSel.fill(pass).catch(()=>{})
  // click login button
  const btn = page.getByRole('button', { name: /登\s*录/ }).first()
  await btn.click().catch(async () => { await page.locator('button').first().click().catch(()=>{}) })
  await page.waitForTimeout(5000)
  console.log('after login url:', page.url())
  await dumpStore('after-login')
  // navigate home
  await page.goto(BASE + '/#/home', { waitUntil: 'networkidle', timeout: 30000 }).catch(()=>{})
  await page.waitForTimeout(4000)
  console.log('home url:', page.url())
  await dumpStore('home')
  // detect which layout
  const info = await page.evaluate(() => ({
    hasAdminLayout: !!document.querySelector('.home-layout-admin'),
    hasSidebarLayout: !!document.querySelector('.home-layout-sidebar'),
    hasUserCard: !!document.querySelector('.sidebar-panel'),
    hasAiPanel: !!document.querySelector('.sidebar-ai-panel, .admin-grid-ai'),
    hasQuickLinks: !!document.querySelector('.sidebar-quick-links, .admin-grid-quick'),
  }))
  console.log('LAYOUT:', JSON.stringify(info))
  await page.screenshot({ path: 'D:/repository/门户/_diag_admin_home.png', fullPage: true })
  console.log('screenshot saved')
} catch (e) {
  console.log('SCRIPT ERR:', e.message)
  console.log('LOGS:', logs.slice(-20).join('\n'))
} finally {
  await browser.close()
}

