import { chromium } from 'playwright'
const BASE = 'http://127.0.0.1:8092'
const browser = await chromium.launch({ headless: true })
const ctx = await browser.newContext({ viewport: { width: 1920, height: 953 } })
const page = await ctx.newPage()

// 1) login via API through same origin (proxy to dev backend)
const loginResp = await page.request.post(BASE + '/api/v3.0/portal/login/login', {
  data: { userName: 'admin', password: 'Zs@2026Aa!' }
})
const lj = await loginResp.json()
const token = lj?.data?.token
console.log('login code:', lj.code, 'token?', !!token, 'len', token?.length)

// 2) inject session
await page.goto(BASE + '/#/login', { waitUntil: 'domcontentloaded' })
