/** 是否根部门：约定 parentId 为 '0'/0/null/undefined 表示无上级 */
function isRootDeptId(deptId) {
  return deptId === undefined || deptId === null || deptId === '' || deptId === 0 || String(deptId) === '0'
}

async function fetchDept(deptId) {
  // 根部门（'0'/0）不请求详情，避免后端「部门不存在」报错拖垮整个登录态解析
  if (isRootDeptId(deptId)) {
    return null
  }
  // 部门详情失败不阻断登录态解析（如无部门管理权限时接口 403）
  const res = await POST('/portal/dept/detail', {}, { params: { deptId }, noMessage: true }).catch(() => null)
  return res?.data || null
}

